-- =====================================================================
-- Emma Accesorios - Esquema v2
-- GENERADO desde las entidades de Doctrine con:
--   php bin/console doctrine:schema:create --dump-sql
-- No editar a mano: el esquema se define en src/AppBundle/Entity.
--
-- Lo normal es NO usar este archivo y crear la base con:
--   php bin/console doctrine:database:create
--   php bin/console doctrine:schema:create
-- Queda acá para quien prefiera importarlo desde phpMyAdmin.
-- =====================================================================

CREATE DATABASE IF NOT EXISTS `emmaaccesorios`
  DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `emmaaccesorios`;

CREATE TABLE producto (IDProducto INT AUTO_INCREMENT NOT NULL, NombreProducto VARCHAR(50) NOT NULL, stockProducto INT DEFAULT 0 NOT NULL, PrecioProducto NUMERIC(12, 2) DEFAULT '0' NOT NULL, costeProduccion NUMERIC(12, 2) DEFAULT '0' NOT NULL, visibility TINYINT(1) DEFAULT '1' NOT NULL, PRIMARY KEY(IDProducto)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
CREATE TABLE venta (IDVenta INT AUTO_INCREMENT NOT NULL, CantidadProducto INT NOT NULL, PrecioUnitario NUMERIC(12, 2) DEFAULT '0' NOT NULL, profit NUMERIC(12, 2) DEFAULT '0' NOT NULL, fechaVenta DATE NOT NULL, Total NUMERIC(12, 2) DEFAULT '0' NOT NULL, IDTicket INT NOT NULL, IDCliente INT NOT NULL, IDProducto INT NOT NULL, INDEX IDX_8FE7EE55C27A5EF3 (IDTicket), INDEX IDX_8FE7EE559F221022 (IDCliente), INDEX IDX_8FE7EE5539B4AD3D (IDProducto), PRIMARY KEY(IDVenta)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
CREATE TABLE proveedores (IDProveedor INT AUTO_INCREMENT NOT NULL, nombre VARCHAR(50) NOT NULL, TelefonoProveedor VARCHAR(20) DEFAULT '' NOT NULL, IDCiudad INT DEFAULT NULL, INDEX IDX_864FA8F1DB5CF6CE (IDCiudad), PRIMARY KEY(IDProveedor)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
CREATE TABLE compras (IDCompra INT AUTO_INCREMENT NOT NULL, FechaCompra DATE NOT NULL, cantidad INT NOT NULL, costo NUMERIC(12, 2) NOT NULL, IDProveedor INT NOT NULL, IDInsumo INT NOT NULL, INDEX IDX_3692E1B723EBCF9F (IDProveedor), INDEX IDX_3692E1B7CB0F09A7 (IDInsumo), PRIMARY KEY(IDCompra)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
CREATE TABLE cliente (IDCliente INT AUTO_INCREMENT NOT NULL, nombreCliente VARCHAR(50) NOT NULL, telefonoCliente VARCHAR(20) DEFAULT '' NOT NULL, visibility TINYINT(1) DEFAULT '1' NOT NULL, IDCiudad INT DEFAULT NULL, INDEX IDX_F41C9B25DB5CF6CE (IDCiudad), PRIMARY KEY(IDCliente)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
CREATE TABLE canjes (IDCanje INT AUTO_INCREMENT NOT NULL, FechaCanje DATE NOT NULL, CantidadProducto INT NOT NULL, CantidadInsumo INT NOT NULL, Profit NUMERIC(12, 2) DEFAULT '0' NOT NULL, IDProveedor INT NOT NULL, IDProducto INT NOT NULL, IDInsumo INT NOT NULL, INDEX IDX_D4CFF30823EBCF9F (IDProveedor), INDEX IDX_D4CFF30839B4AD3D (IDProducto), INDEX IDX_D4CFF308CB0F09A7 (IDInsumo), PRIMARY KEY(IDCanje)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
CREATE TABLE usuario (IDUsuario INT AUTO_INCREMENT NOT NULL, NombreUsuario VARCHAR(50) NOT NULL, Rol INT DEFAULT 2 NOT NULL, UsuarioEmail VARCHAR(100) NOT NULL, PasswordHash VARCHAR(255) NOT NULL, Activo TINYINT(1) DEFAULT '1' NOT NULL, IntentosFallidos INT DEFAULT 0 NOT NULL, BloqueadoHasta DATETIME DEFAULT NULL, UltimoLogin DATETIME DEFAULT NULL, FechaCreacion DATETIME NOT NULL, UNIQUE INDEX uq_usuario_email (UsuarioEmail), PRIMARY KEY(IDUsuario)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
CREATE TABLE ciudad (IDCiudad INT AUTO_INCREMENT NOT NULL, NombreCiudad VARCHAR(50) NOT NULL, Provincia INT NOT NULL, PRIMARY KEY(IDCiudad)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
CREATE TABLE insumo (IDInsumo INT AUTO_INCREMENT NOT NULL, NombreInsumo VARCHAR(50) NOT NULL, Stock INT DEFAULT 0 NOT NULL, precio NUMERIC(12, 2) DEFAULT '0' NOT NULL, DescuentoPactadoCanje INT DEFAULT 0 NOT NULL, visibility TINYINT(1) DEFAULT '1' NOT NULL, PRIMARY KEY(IDInsumo)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
CREATE TABLE ticket (IDTicket INT AUTO_INCREMENT NOT NULL, Fecha DATETIME NOT NULL, CProductos INT DEFAULT 0 NOT NULL, Valor NUMERIC(12, 2) DEFAULT '0' NOT NULL, IDCliente INT NOT NULL, INDEX IDX_97A0ADA39F221022 (IDCliente), PRIMARY KEY(IDTicket)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_general_ci` ENGINE = InnoDB;
ALTER TABLE venta ADD CONSTRAINT FK_8FE7EE55C27A5EF3 FOREIGN KEY (IDTicket) REFERENCES ticket (IDTicket);
ALTER TABLE venta ADD CONSTRAINT FK_8FE7EE559F221022 FOREIGN KEY (IDCliente) REFERENCES cliente (IDCliente);
ALTER TABLE venta ADD CONSTRAINT FK_8FE7EE5539B4AD3D FOREIGN KEY (IDProducto) REFERENCES producto (IDProducto);
ALTER TABLE proveedores ADD CONSTRAINT FK_864FA8F1DB5CF6CE FOREIGN KEY (IDCiudad) REFERENCES ciudad (IDCiudad);
ALTER TABLE compras ADD CONSTRAINT FK_3692E1B723EBCF9F FOREIGN KEY (IDProveedor) REFERENCES proveedores (IDProveedor);
ALTER TABLE compras ADD CONSTRAINT FK_3692E1B7CB0F09A7 FOREIGN KEY (IDInsumo) REFERENCES insumo (IDInsumo);
ALTER TABLE cliente ADD CONSTRAINT FK_F41C9B25DB5CF6CE FOREIGN KEY (IDCiudad) REFERENCES ciudad (IDCiudad);
ALTER TABLE canjes ADD CONSTRAINT FK_D4CFF30823EBCF9F FOREIGN KEY (IDProveedor) REFERENCES proveedores (IDProveedor);
ALTER TABLE canjes ADD CONSTRAINT FK_D4CFF30839B4AD3D FOREIGN KEY (IDProducto) REFERENCES producto (IDProducto);
ALTER TABLE canjes ADD CONSTRAINT FK_D4CFF308CB0F09A7 FOREIGN KEY (IDInsumo) REFERENCES insumo (IDInsumo);
ALTER TABLE ticket ADD CONSTRAINT FK_97A0ADA39F221022 FOREIGN KEY (IDCliente) REFERENCES cliente (IDCliente);
